  "knowledge": "Conservation Backlog Risk (CBR)",
  "description": "Quantifies the risk associated with delayed conservation treatments.",
  "definition": "Calculated as: ('Conservation Priority Index (CPI)' * (Days since last cleaning date - Cleaning interval days)) / 100. Higher values indicate higher risk."
}

